343	// findingFixNecessity は指摘の必要度を返す。判定を省略した指摘は、参照先の必要度。
344	// 分からなければ空。
345	func findingFixNecessity(doc *recordDoc, ri int, fd recordFinding) string {
346		if !judgmentOmitted(fd) {
347			return fd.FixNecessity
348		}
349		if target, _ := belowMinimumRefTarget(doc, ri, fd.BelowMinimumRef); target != nil {
350			return target.FixNecessity
351		}
352		return ""
353	}
